css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: calc(var(--loader-size) * .72); height: var(--loader-size); position: relative; overflow: hidden; border-radius: 8%; background: linear-gradient(#1e293b, #0b1220); box-shadow: inset 0 0 0 2px #334155; }
.loader::before { content: ''; position: absolute; top: 8%; left: 8%; width: 84%; height: 56%; background: repeating-linear-gradient(to bottom, transparent 0 26%, rgba(255, 255, 255, .16) 26% 30%); }
.loader::after { content: ''; position: absolute; bottom: 6%; left: 10%; width: 80%; height: 18%; border-radius: 4px; background: rgba(255, 255, 255, .06); box-shadow: inset 0 0 0 2px rgba(255, 255, 255, .22); }
.loader span { position: absolute; top: 12%; width: 18%; height: 12%; border-radius: 3px; background: var(--accent); animation: vend calc(var(--loader-speed) * 2.6) ease-in infinite; }
.loader span:nth-child(1) { left: 13%; }
.loader span:nth-child(2) { left: 41%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * .87); }
.loader span:nth-child(3) { left: 69%; animation-delay: calc(var(--loader-speed) * 1.74); }
@keyframes vend { 0% { opacity: 0; transform: translate(0, 0) rotate(0deg); } 10% { opacity: 1; } 52% { transform: translate(0, calc(var(--loader-size) * .62)) rotate(148deg); } 72% { opacity: 1; transform: translate(0, calc(var(--loader-size) * .62)) rotate(160deg); } 100% { opacity: 0; transform: translate(0, calc(var(--loader-size) * .62)) rotate(160deg); } }
